from typing import Sequence


def _validate_2d(M: Sequence[Sequence[float]], name: str) -> tuple[int, int]:
    if not M or not M[0]:
        raise ValueError(f"Matrix {name} must be non-empty.")
    cols = len(M[0])
    for idx, row in enumerate(M):
        if len(row) != cols:
            raise ValueError(f"Matrix {name} is ragged at row {idx}.")
    return len(M), cols


