class MLPBlock:
    """Two-layer feed-forward network: H = ReLU(X W1 + b1), Y = H W2 + b2."""

    def __init__(
        self,
        W1: list[list[float]],
        b1: list[float],
        W2: list[list[float]],
        b2: list[float],
    ) -> None:
        self.W1, self.b1 = W1, b1
        self.W2, self.b2 = W2, b2

    @staticmethod
    def _add_bias(X: list[list[float]], b: list[float], relu: bool) -> list[list[float]]:
        out: list[list[float]] = []
        for row in X:
            shifted = [val + bias for val, bias in zip(row, b)]
            out.append([max(0.0, v) for v in shifted] if relu else shifted)
        return out

    def forward(self, X: Sequence[Sequence[float]]) -> list[list[float]]:
        hidden = self._add_bias(matmul(X, self.W1), self.b1, relu=True)
        return self._add_bias(matmul(hidden, self.W2), self.b2, relu=False)

