class LinearSystemSolver:
    """Computes determinant and solves A x = b via Gauss-Jordan inversion."""

    @staticmethod
    def determinant(A: np.ndarray) -> float:
        M = np.array(A, dtype=np.float64, copy=True)
        if M.ndim != 2 or M.shape[0] != M.shape[1] or M.shape[0] == 0:
            raise ValueError("Determinant requires a non-empty square 2D matrix.")
        n = M.shape[0]
        if n == 2:
            return float(M[0, 0] * M[1, 1] - M[0, 1] * M[1, 0])
        det = 1.0
        for col in range(n):
            pivot_row = col + int(np.argmax(np.abs(M[col:, col])))
            if abs(M[pivot_row, col]) < 1e-12:
                return 0.0
            if pivot_row != col:
                M[[col, pivot_row]] = M[[pivot_row, col]]
                det = -det
            det *= M[col, col]
            for r in range(col + 1, n):
                factor = M[r, col] / M[col, col]
                M[r, col:] -= factor * M[col, col:]
        return float(det)

    def solve(self, A: np.ndarray, b: np.ndarray) -> np.ndarray:
        A_inv = invert_matrix(A)
        return A_inv @ np.asarray(b, dtype=np.float64)
